        String body = """
                {
                  "itens": [{"nome": "X", "precoUnitario": 600.00, "quantidade": 2, "pesoKg": 1.0}],
                  "modalidadeEntrega": "ECONOMICA",
                  "formaPagamento": "BOLETO",
