    private static final String URL = "/checkout/resumo";

    // Exemplo 1: Camiseta 79,90×2 + Tênis 249,90×1, EXPRESSA, BEMVINDO10, PIX, BRONZE, NORTE
    // subtotal 409,70 · cupom 40,97 · frete 33,10 · prazo 2 · seguro 10,24 ·
